def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    OP_INT = 0
    OP_CELL = 1
    OP_NEG = 2
    OP_BIN = 3
    OP_IF = 4
    OP_FUNC = 5

    FN_SUM = 0
    FN_MIN = 1
    FN_MAX = 2

    ARG_RANGE = 0
    ARG_EXPR = 1

    CONT_CELL = 0
    CONT_NEG = 1
    CONT_BIN_L = 2
    CONT_BIN_R = 3
    CONT_IF_L = 4
    CONT_IF_R = 5
    CONT_FUNC = 6

    def tokenize(expr: str) -> list:
        tokens = []
        i = 0
        n = len(expr)
        while i < n:
            ch = expr[i]
            if ch.isspace():
                i += 1
            elif ch.isdigit():
                j = i + 1
                while j < n and expr[j].isdigit():
                    j += 1
                tokens.append(("INT", int(expr[i:j])))
                i = j
            elif "A" <= ch <= "Z":
                j = i + 1
                while j < n and (expr[j].isdigit() or "A" <= expr[j] <= "Z"):
                    j += 1
                word = expr[i:j]
                if word in ("SUM", "MIN", "MAX", "IF"):
                    tokens.append(("FUNC", word))
                else:
                    c = ord(word[0]) - 65
                    r = int(word[1:]) - 1
                    tokens.append(("CELL", r * 26 + c, r, c))
                i = j
            elif ch == "<":
                if i + 1 < n and expr[i + 1] in ("=", ">"):
                    tokens.append(("OP", expr[i:i + 2]))
                    i += 2
                else:
                    tokens.append(("OP", "<"))
                    i += 1
            elif ch == ">":
                if i + 1 < n and expr[i + 1] == "=":
                    tokens.append(("OP", ">="))
                    i += 2
                else:
                    tokens.append(("OP", ">"))
                    i += 1
            elif ch == "=":
                tokens.append(("OP", "="))
                i += 1
            else:
                tokens.append((ch, ch))
                i += 1
        tokens.append(("EOF", None))
        return tokens

    def parse(expr: str):
        tokens = tokenize(expr)
        pos = 0

        def parse_expr():
            nonlocal pos
            node = parse_term()
            while tokens[pos][0] in ("+", "-"):
                op = tokens[pos][0]
                pos += 1
                right = parse_term()
                node = (OP_BIN, op, node, right)
            return node

        def parse_term():
            nonlocal pos
            node = parse_unary()
            while tokens[pos][0] in ("*", "/"):
                op = tokens[pos][0]
                pos += 1
                right = parse_unary()
                node = (OP_BIN, op, node, right)
            return node

        def parse_unary():
            nonlocal pos
            neg_count = 0
            while tokens[pos][0] == "-":
                neg_count += 1
                pos += 1
            node = parse_atom()
            if neg_count & 1:
                node = (OP_NEG, node)
            return node

        def parse_atom():
            nonlocal pos
            tok = tokens[pos]
            kind = tok[0]
            if kind == "INT":
                pos += 1
                return (OP_INT, tok[1])
            if kind == "CELL":
                pos += 1
                return (OP_CELL, tok[1])
            if kind == "(":
                pos += 1
                node = parse_expr()
                pos += 1
                return node
            fn = tok[1]
            pos += 2
            if fn == "IF":
                left = parse_expr()
                op = tokens[pos][1]
                pos += 1
                right = parse_expr()
                pos += 1
                then_e = parse_expr()
                pos += 1
                else_e = parse_expr()
                pos += 1
                return (OP_IF, op, left, right, then_e, else_e)
            fn_kind = FN_SUM if fn == "SUM" else (FN_MIN if fn == "MIN" else FN_MAX)
            args = []
            while True:
                if tokens[pos][0] == "CELL" and tokens[pos + 1][0] == ":":
                    _, _, r1, c1 = tokens[pos]
                    _, _, r2, c2 = tokens[pos + 2]
                    pos += 3
                    r_lo, r_hi = (r1, r2) if r1 <= r2 else (r2, r1)
                    c_lo, c_hi = (c1, c2) if c1 <= c2 else (c2, c1)
                    args.append((ARG_RANGE, r_lo, r_hi, c_lo, c_hi))
                else:
                    args.append((ARG_EXPR, parse_expr()))
                if tokens[pos][0] == ",":
                    pos += 1
                else:
                    pos += 1
                    break
            return (OP_FUNC, fn_kind, args)

        return parse_expr()

    total = 2574
    present = [False] * total
    state = [0] * total  # 0: unvisited, 1: visiting, 2: done
    values: list[int | str] = [0] * total
    asts: list = [None] * total

    names: list[tuple[str, int]] = []
    for name, content in cells.items():
        c = ord(name[0]) - 65
        r = int(name[1:]) - 1
        idx = r * 26 + c
        present[idx] = True
        names.append((name, idx))
        s = content.strip()
        if s.startswith("="):
            asts[idx] = parse(s[1:])
        else:
            values[idx] = int(s)
            state[idx] = 2

    def eval_cell(start_idx: int) -> None:
        state[start_idx] = 1
        stack: list = [(CONT_CELL, start_idx)]
        node = asts[start_idx]

        def advance_func(fn_kind, args, arg_i, r, c, acc):
            while arg_i < len(args):
                arg = args[arg_i]
                if arg[0] == ARG_RANGE:
                    _, r_lo, r_hi, c_lo, c_hi = arg
                    if r == -1:
                        r = r_lo
                        c = c_lo
                    while r <= r_hi:
                        base = r * 26
                        while c <= c_hi:
                            idx = base + c
                            c += 1
                            if not present[idx]:
                                continue
                            st = state[idx]
                            if st == 2:
                                v = values[idx]
                                if isinstance(v, str):
                                    return 0, v
                                if fn_kind == FN_SUM:
                                    acc += v
                                elif fn_kind == FN_MIN:
                                    if acc is None or v < acc:
                                        acc = v
                                else:
                                    if acc is None or v > acc:
                                        acc = v
                            elif st == 1:
                                return 0, "#CYCLE!"
                            else:
                                if c > c_hi:
                                    r += 1
                                    c = c_lo
                                if r > r_hi:
                                    stack.append((CONT_FUNC, fn_kind, args, arg_i + 1, -1, 0, acc))
                                else:
                                    stack.append((CONT_FUNC, fn_kind, args, arg_i, r, c, acc))
                                state[idx] = 1
                                stack.append((CONT_CELL, idx))
                                return 1, asts[idx]
                        r += 1
                        c = c_lo
                    arg_i += 1
                    r = -1
                else:
                    stack.append((CONT_FUNC, fn_kind, args, arg_i + 1, -1, 0, acc))
                    return 1, arg[1]
            return 0, (0 if acc is None else acc)

        evaluating = True
        val: int | str = 0
        while True:
            if evaluating:
                op = node[0]
                if op == OP_INT:
                    val = node[1]
                    evaluating = False
                elif op == OP_CELL:
                    idx = node[1]
                    if not present[idx]:
                        val = 0
                        evaluating = False
                    else:
                        st = state[idx]
                        if st == 2:
                            val = values[idx]
                            evaluating = False
                        elif st == 1:
                            val = "#CYCLE!"
                            evaluating = False
                        else:
                            state[idx] = 1
                            stack.append((CONT_CELL, idx))
                            node = asts[idx]
                elif op == OP_NEG:
                    stack.append((CONT_NEG,))
                    node = node[1]
                elif op == OP_BIN:
                    stack.append((CONT_BIN_L, node[1], node[3]))
                    node = node[2]
                elif op == OP_IF:
                    stack.append((CONT_IF_L, node[1], node[3], node[4], node[5]))
                    node = node[2]
                else:
                    fn_kind = node[1]
                    acc = 0 if fn_kind == FN_SUM else None
                    mode, payload = advance_func(fn_kind, node[2], 0, -1, 0, acc)
                    if mode == 1:
                        node = payload
                    else:
                        val = payload
                        evaluating = False
            else:
                if not stack:
                    return
                frame = stack.pop()
                kind = frame[0]
                if kind == CONT_CELL:
                    idx = frame[1]
                    values[idx] = val
                    state[idx] = 2
                elif kind == CONT_NEG:
                    if not isinstance(val, str):
                        val = -val
                elif kind == CONT_BIN_L:
                    if not isinstance(val, str):
                        stack.append((CONT_BIN_R, frame[1], val))
                        node = frame[2]
                        evaluating = True
                elif kind == CONT_BIN_R:
                    if not isinstance(val, str):
                        bop = frame[1]
                        lv = frame[2]
                        if bop == "+":
                            val = lv + val
                        elif bop == "-":
                            val = lv - val
                        elif bop == "*":
                            val = lv * val
                        else:
                            if val == 0:
                                val = "#DIV/0!"
                            else:
                                q = abs(lv) // abs(val)
                                val = -q if (lv < 0) ^ (val < 0) else q
                elif kind == CONT_IF_L:
                    if not isinstance(val, str):
                        stack.append((CONT_IF_R, frame[1], val, frame[3], frame[4]))
                        node = frame[2]
                        evaluating = True
                elif kind == CONT_IF_R:
                    if not isinstance(val, str):
                        cop = frame[1]
                        lv = frame[2]
                        if cop == "=":
                            cond = lv == val
                        elif cop == "<>":
                            cond = lv != val
                        elif cop == "<":
                            cond = lv < val
                        elif cop == "<=":
                            cond = lv <= val
                        elif cop == ">":
                            cond = lv > val
                        else:
                            cond = lv >= val
                        node = frame[3] if cond else frame[4]
                        evaluating = True
                else:
                    if not isinstance(val, str):
                        _, fn_kind, args, arg_i, r, c, acc = frame
                        if fn_kind == FN_SUM:
                            acc += val
                        elif fn_kind == FN_MIN:
                            if acc is None or val < acc:
                                acc = val
                        else:
                            if acc is None or val > acc:
                                acc = val
                        mode, payload = advance_func(fn_kind, args, arg_i, r, c, acc)
                        if mode == 1:
                            node = payload
                            evaluating = True
                        else:
                            val = payload

    for _, idx in names:
        if state[idx] == 0:
            eval_cell(idx)

    return {name: values[idx] for name, idx in names}
